const parseSocialVideoUrl = (urlStr: string = "", isMuted: boolean = false): { type: "iframe" | "video"; embedUrl: string } => {
  if (!urlStr) {
    return {
      type: "video",
      embedUrl: "https://assets.mixkit.co/videos/preview/mixkit-golden-olive-oil-poured-into-a-bowl-43485-large.mp4"
    };
  }

  const url = urlStr.trim();

  // YouTube Shorts / Standard Videos
  if (url.includes("youtube.com") || url.includes("youtu.be")) {
    let videoId = "";
    if (url.includes("youtu.be/")) {
      videoId = url.split("youtu.be/")[1]?.split("?")[0] || "";
    } else if (url.includes("embed/")) {
      videoId = url.split("embed/")[1]?.split("?")[0] || "";
    } else if (url.includes("shorts/")) {
      videoId = url.split("shorts/")[1]?.split("?")[0] || "";
    } else if (url.includes("v=")) {
      videoId = url.split("v=")[1]?.split("&")[0] || "";
    }
    if (videoId) {
      return {
        type: "iframe",
        embedUrl: `https://www.youtube.com/embed/${videoId}?autoplay=1&mute=${isMuted ? 1 : 0}&muted=${isMuted ? 1 : 0}&controls=0&modestbranding=1&rel=0&loop=1&playlist=${videoId}&playsinline=1&enablejsapi=1`
      };
    }
  }

  // Instagram Reels
  if (url.includes("instagram.com")) {
    const reelMatch = url.match(/\/(?:reel|p)\/([a-zA-Z0-9_-]+)/);
    if (reelMatch && reelMatch[1]) {
      const reelId = reelMatch[1];
      return {
        type: "iframe",
        embedUrl: `https://www.instagram.com/reel/${reelId}/embed?autoplay=1&mute=${isMuted ? 1 : 0}&muted=${isMuted ? 1 : 0}&playsinline=1`
      };
    }
  }

  // TikTok Videos/Reels
  if (url.includes("tiktok.com")) {
    let videoId = "";
    const matches = url.match(/\/video\/(\d+)/);
    if (matches && matches[1]) {
      videoId = matches[1];
    } else {
      const embedMatches = url.match(/\/embed\/(\d+)/);
      if (embedMatches && embedMatches[1]) {
        videoId = embedMatches[1];
      }
    }
    if (videoId) {
      return {
        type: "iframe",
        embedUrl: `https://www.tiktok.com/embed/v2/${videoId}?autoplay=1&mute=${isMuted ? 1 : 0}&muted=${isMuted ? 1 : 0}&playsinline=1`
      };
    }
    const lastSegment = url.split("/").pop()?.split("?")[0] || "";
    if (/^\d+$/.test(lastSegment)) {
      return {
        type: "iframe",
        embedUrl: `https://www.tiktok.com/embed/v2/${lastSegment}?autoplay=1&mute=${isMuted ? 1 : 0}&muted=${isMuted ? 1 : 0}&playsinline=1`
      };
    }
  }

  // Facebook Reels & Videos
  if (url.includes("facebook.com") || url.includes("fb.watch") || url.includes("fb.com")) {
    return {
      type: "iframe",
      embedUrl: `https://www.facebook.com/plugins/video.php?href=${encodeURIComponent(url)}&show_text=0&autoplay=1&mute=${isMuted ? 1 : 0}&muted=${isMuted ? 1 : 0}`
    };
  }

  // Direct video assets
  return {
    type: "video",
    embedUrl: url
  };
};

const hexToRgba = (hex: string, alpha: number) => {
  if (!hex) return `rgba(235, 141, 112, ${alpha})`;
  const cleanHex = hex.replace("#", "");
  const r = parseInt(cleanHex.slice(0, 2), 16);
  const g = parseInt(cleanHex.slice(2, 4), 16);
  const b = parseInt(cleanHex.slice(4, 6), 16);
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
};

const isAnnouncementActive = (store: any) => {
  if (!store || !store.announcement || !store.announcement.enabled || !store.announcement.text) {
    return false;
  }
  if (store.announcement.expiresAt) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const expiry = new Date(store.announcement.expiresAt);
    if (!isNaN(expiry.getTime())) {
      expiry.setHours(23, 59, 59, 999);
      return today <= expiry;
    }
  }
  return true;
};

