const getGridColsClass = (perRow: number) => {
  switch (perRow) {
    case 1:
      return "grid grid-cols-1 gap-5";
    case 2:
      return "grid grid-cols-1 sm:grid-cols-2 gap-5";
    case 3:
      return "grid grid-cols-2 sm:grid-cols-3 gap-5";
    case 4:
      return "grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-5";
    case 5:
      return "grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 xl:grid-cols-5 gap-5";
    case 6:
      return "grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 xl:grid-cols-5 2xl:grid-cols-6 gap-5";
    case 7:
      return "grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 2xl:grid-cols-7 gap-5";
    default:
      return "grid grid-cols-2 md:grid-cols-4 gap-5";
  }
};

function StoreProductsCarousel({
  store,
  wishlist,
  handleToggleWishlist,
  isMobileViewport,
  setSelectedProduct,
  setSelectedStore,
  handleAddToCart,
  getOptimizedImageUrl,
  accentColor = "#db2777",
  showMap = true,
  isLoading = false,
  subcategories = [],
  mainCategories = [],
  currentLanguage = "en"
}: {
  store: MerchantStore;
  wishlist: any[];
  handleToggleWishlist: (id: string) => void;
  isMobileViewport: boolean;
  setSelectedProduct: (p: any) => void;
  setSelectedStore: (s: any) => void;
  handleAddToCart: (p: any, s: any) => void;
  getOptimizedImageUrl: (url: string, isMobile: boolean) => string;
  accentColor?: string;
  showMap?: boolean;
  isLoading?: boolean;
  subcategories?: Subcategory[];
  mainCategories?: MainCategory[];
  currentLanguage?: Language;
}) {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [scrollLeft, setScrollLeft] = useState(0);
  const [containerWidth, setContainerWidth] = useState(600);
  const [hoveredIndex, setHoveredIndex] = useState<number | null>(null);
  const [isMouseOverArea, setIsMouseOverArea] = useState(false);
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(true);

  // Drag-to-scroll & momentum physics state
  const isDown = useRef(false);
  const startX = useRef(0);
  const scrollLeftVal = useRef(0);
  const isDragging = useRef(false);
  
  const momentumId = useRef<number | null>(null);
  const scrollAnimId = useRef<number | null>(null);
  const velocity = useRef(0);
  const lastX = useRef(0);
  const lastTime = useRef(0);

  const customScrollTo = (element: HTMLElement, to: number, duration = 200) => {
    if (scrollAnimId.current) {
      cancelAnimationFrame(scrollAnimId.current);
    }
    const start = element.scrollLeft;
    const change = to - start;
    const startTime = performance.now();

    const animateScroll = (timestamp: number) => {
      const elapsed = timestamp - startTime;
      const progress = Math.min(elapsed / duration, 1);
      
      // Snappy and ultra-smooth easeOutQuart curve: starts fast, decelerates beautifully
      const ease = 1 - Math.pow(1 - progress, 4);

      element.scrollLeft = start + change * ease;

      if (progress < 1) {
        scrollAnimId.current = requestAnimationFrame(animateScroll);
      } else {
        checkScrollLimit();
      }
    };

    scrollAnimId.current = requestAnimationFrame(animateScroll);
  };

  const snapToItem = () => {
    if (!scrollContainerRef.current) return;
    const container = scrollContainerRef.current;
    const firstChild = container.firstElementChild as HTMLElement;
    if (firstChild) {
      const gap = 14;
      const itemWidth = firstChild.getBoundingClientRect().width || firstChild.offsetWidth;
      const scrollAmount = itemWidth + gap;
      const index = Math.round(container.scrollLeft / scrollAmount);
      customScrollTo(container, index * scrollAmount, 180); // ultra-snappy snap duration
    }
  };

  const startMomentumOrSnap = () => {
    if (!scrollContainerRef.current) return;
    
    if (isDragging.current && Math.abs(velocity.current) > 0.15) {
      let vel = velocity.current * 16; // scale initial velocity for premium feel
      const friction = 0.95; // damping deceleration physics
      const container = scrollContainerRef.current;
      
      const tick = () => {
        if (Math.abs(vel) < 0.25) {
          snapToItem();
          return;
        }
        
        container.scrollLeft += vel;
        vel *= friction;
        checkScrollLimit();
        
        momentumId.current = requestAnimationFrame(tick);
      };
      
      momentumId.current = requestAnimationFrame(tick);
    } else {
      snapToItem();
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!scrollContainerRef.current) return;
    
    // Interrupt active animations
    if (momentumId.current) cancelAnimationFrame(momentumId.current);
    if (scrollAnimId.current) cancelAnimationFrame(scrollAnimId.current);

    isDown.current = true;
    isDragging.current = false;
    startX.current = e.pageX - scrollContainerRef.current.offsetLeft;
    scrollLeftVal.current = scrollContainerRef.current.scrollLeft;
    
    lastX.current = e.pageX;
    lastTime.current = performance.now();
    velocity.current = 0;
    
    scrollContainerRef.current.style.scrollBehavior = "auto";
  };

  const handleMouseLeave = () => {
    if (!isDown.current) return;
    isDown.current = false;
    startMomentumOrSnap();
  };

  const handleMouseUp = () => {
    if (!isDown.current) return;
    isDown.current = false;
    startMomentumOrSnap();
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDown.current || !scrollContainerRef.current) return;
    e.preventDefault();
    
    const x = e.pageX - scrollContainerRef.current.offsetLeft;
    const walk = (x - startX.current) * 1.6;
    
    if (Math.abs(walk) > 10) {
      isDragging.current = true;
    }
    
    scrollContainerRef.current.scrollLeft = scrollLeftVal.current - walk;
    
    const now = performance.now();
    const deltaX = e.pageX - lastX.current;
    const deltaTime = now - lastTime.current;
    if (deltaTime > 0) {
      velocity.current = -deltaX / deltaTime;
    }
    lastX.current = e.pageX;
    lastTime.current = now;
    
    checkScrollLimit();
  };

  const checkScrollLimit = () => {
    if (scrollContainerRef.current) {
      const { scrollLeft, scrollWidth, clientWidth } = scrollContainerRef.current;
      setCanScrollLeft(scrollLeft > 6);
      setCanScrollRight(scrollLeft + clientWidth < scrollWidth - 6);
    }
  };

  useEffect(() => {
    checkScrollLimit();
    const container = scrollContainerRef.current;
    if (container) {
      let scrollTimeout: number | null = null;
      const handleScrollRealtime = () => {
        if (scrollTimeout) {
          cancelAnimationFrame(scrollTimeout);
        }
        scrollTimeout = requestAnimationFrame(() => {
          setScrollLeft(container.scrollLeft);
          checkScrollLimit();
        });
      };
      container.addEventListener("scroll", handleScrollRealtime, { passive: true });
      
      const handleResize = () => {
        setContainerWidth(container.clientWidth);
        checkScrollLimit();
      };
      window.addEventListener("resize", handleResize);

      // Initial dimensions
      setScrollLeft(container.scrollLeft);
      setContainerWidth(container.clientWidth);

      return () => {
        if (container) {
          container.removeEventListener("scroll", handleScrollRealtime);
        }
        if (scrollTimeout) {
          cancelAnimationFrame(scrollTimeout);
        }
        if (momentumId.current) {
          cancelAnimationFrame(momentumId.current);
        }
        if (scrollAnimId.current) {
          cancelAnimationFrame(scrollAnimId.current);
        }
        window.removeEventListener("resize", handleResize);
      };
    }
  }, [store.products]);

  const handleScroll = (direction: "left" | "right") => {
    if (scrollContainerRef.current) {
      const container = scrollContainerRef.current;
      const firstChild = container.firstElementChild as HTMLElement;
      if (firstChild) {
        const gap = 14; // gap-3.5 is 14px
        const itemWidth = firstChild.getBoundingClientRect().width || firstChild.offsetWidth;
        const scrollAmount = itemWidth + gap;
        
        // Calculate how many items are fully or mostly visible in the viewport
        const visibleCount = Math.max(1, Math.floor(container.clientWidth / scrollAmount));
        // Scroll multiple items at once (page size minus 1 overlapping item for excellent visual continuity)
        const itemsToScroll = Math.max(1, visibleCount > 1 ? visibleCount - 1 : 1);
        const scrollDistance = scrollAmount * itemsToScroll;
        
        let targetScroll = direction === "left" 
          ? container.scrollLeft - scrollDistance 
          : container.scrollLeft + scrollDistance;
        
        // Round to nearest item start position for pristine accuracy
        const index = Math.round(targetScroll / scrollAmount);
        targetScroll = index * scrollAmount;
        
        customScrollTo(container, targetScroll, 200); // super responsive, smooth and speedy 200ms motion
      }
    }
  };

  return (
    <div 
      className="flex items-center bg-stone-50/40 hover:bg-stone-50/75 rounded-3xl border border-stone-100/70 transition-all w-full animate-fadeIn relative px-3 py-4 overflow-visible h-[300px]"
      onClick={(e) => e.stopPropagation()}
      onMouseEnter={() => setIsMouseOverArea(true)}
      onMouseLeave={() => {
        setIsMouseOverArea(false);
        setHoveredIndex(null);
      }}
      onTouchStart={() => setIsMouseOverArea(true)}
    >
      {/* Left Scroll Button */}
      <button
        type="button"
        onClick={(e) => {
          e.stopPropagation();
          handleScroll("left");
        }}
        className={`absolute -left-[18px] top-[110px] -translate-y-1/2 z-20 w-10 h-10 rounded-full bg-white border border-slate-200/90 shadow-md flex items-center justify-center hover:scale-115 active:scale-95 transition-all duration-200 cursor-pointer focus:outline-none ${
          canScrollLeft ? "opacity-100 pointer-events-auto" : "opacity-0 pointer-events-none scale-90"
        }`}
        style={{ color: accentColor }}
        aria-label="Scroll Left"
      >
        <ChevronsLeft className="w-5 h-5 stroke-[2.5]" />
      </button>

      {/* Decorative vertical brand/header color banner on the left */}
      <div 
        className="h-[250px] rounded-r-md rounded-l-sm shrink-0 transition-all duration-300 p-0 overflow-hidden"
        style={{ 
          backgroundColor: accentColor, 
          opacity: canScrollLeft ? 0 : 1.0,
          width: canScrollLeft ? "0px" : "10px",
          marginRight: canScrollLeft ? "0px" : "8px",
          marginLeft: canScrollLeft ? "0px" : "-15px"
        }}
      />

      {/* Horizontal scroll container */}
      <div 
        ref={scrollContainerRef}
        id={`store-products-scroll-${store.id}`}
        onMouseDown={handleMouseDown}
        onMouseLeave={handleMouseLeave}
        onMouseUp={handleMouseUp}
        onMouseMove={handleMouseMove}
        className="flex gap-3.5 overflow-x-auto w-full py-4 pr-1 scrollbar-none snap-x snap-mandatory cursor-grab active:cursor-grabbing select-none"
        style={{ 
          scrollbarWidth: "none", 
          msOverflowStyle: "none",
          WebkitOverflowScrolling: "touch"
        }}
      >
        {isLoading ? (
          Array.from({ length: 5 }).map((_, idx) => (
            <div
              key={`carousel-skeleton-${idx}`}
              className="flex-none snap-start h-[230px] ml-0 pl-3 pr-3 pt-3 rounded-2xl overflow-hidden border border-stone-100 bg-white transition-all duration-300 ease-out relative flex flex-col justify-between select-none"
              style={{
                width: showMap ? "calc((100% - 60px) / 5.5)" : "calc((100% - 100px) / 8.5)",
                minWidth: "145px",
                maxWidth: "160px",
              }}
            >
              <YumeProductCardSkeleton />
            </div>
          ))
        ) : (
          store.products.map((product, index) => {
            const isWish = wishlist.includes(product.id || product.name);
            
            // Geometry Cover Flow Style Computations
            let scale = 1;
            let opacity = 1;
            let zIndex = 10;
            let translateY = 0;
            let isFocused = false;

            if (isMouseOverArea) {
              const approxItemWidth = 145;
              const approxGap = 14;
              const step = approxItemWidth + approxGap;
              
              // Center of the current item relative to the scrolling container
              const itemCenter = index * step + approxItemWidth / 2;
              
              // Center of the viewport of the scrolling container
              const viewportCenter = scrollLeft + containerWidth / 2;

              // Distance in units of item steps
              const distance = (itemCenter - viewportCenter) / step;
              const absDistance = Math.abs(distance);

              if (absDistance < 0.6) {
                // Highly Centered Active Card - Sits proudly at the absolute front
                const factor = 1 - absDistance / 0.6; // 0 to 1
                scale = 1.0 + 0.15 * factor; // Up to 1.15
                opacity = 1.0;
                zIndex = 30;
                translateY = -12 * factor; // Pulled upward
                isFocused = factor > 0.45;
              } else if (absDistance < 1.6) {
                // Close left/right cards - sloping down smoothly
                const factor = 1 - (absDistance - 0.6) / 1.0; // 0 to 1
                scale = 0.92 + 0.08 * factor; // 0.92 to 1.0
                opacity = 0.78 + 0.22 * factor; // 0.78 to 1.0
                zIndex = 20;
                translateY = -4 * factor;
              } else if (absDistance < 2.6) {
                // Further away adjacent items - receding further
                const factor = 1 - (absDistance - 1.6) / 1.0; // 0 to 1
                scale = 0.83 + 0.09 * factor; // 0.83 to 0.92
                opacity = 0.45 + 0.33 * factor; // 0.45 to 0.78
                zIndex = 15;
              } else {
                // Far away background items represent structural depth
                scale = 0.83;
                opacity = 0.4;
                zIndex = 10;
              }

              const isHovered = hoveredIndex === index;
              if (isHovered) {
                scale = 1.18;
                opacity = 1.0;
                zIndex = 50; // Pop above everything else
                translateY = -16;
              }
            }

            const isHovered = hoveredIndex === index;

            return (
              <motion.div
                key={product.id}
                onClick={(e) => {
                  e.stopPropagation();
                  if (isDragging.current) return; // Prevent clicking when swiping/dragging
                  setSelectedProduct(product);
                  setSelectedStore(store);
                }}
                onMouseEnter={() => setHoveredIndex(index)}
                onMouseLeave={() => setHoveredIndex(null)}
                initial={{ opacity: 0, y: 30, scale: 0.9 }}
                whileInView={{ opacity: opacity, y: translateY, scale: scale }}
                viewport={{ once: true, margin: "-20px" }}
                transition={{ 
                  duration: 0.6, 
                  delay: index * 0.04, 
                  ease: [0.21, 1.11, 0.81, 0.99] 
                }}
                className="flex-none snap-start h-[230px] ml-0 pl-0 pr-0 pt-0 rounded-2xl overflow-hidden border bg-white transition-all duration-300 ease-out relative flex flex-col justify-between group cursor-pointer pb-2 select-none"
                style={{
                  width: showMap ? "calc((100% - 60px) / 5.5)" : "calc((100% - 100px) / 8.5)",
                  minWidth: "145px",
                  maxWidth: "160px",
                  zIndex: zIndex,
                  boxShadow: isHovered || isFocused 
                    ? "0 22px 45px rgba(0,0,0,0.18)" 
                    : "0 4px 12px rgba(0,0,0,0.03)",
                  borderColor: isHovered || isFocused ? "#cbd5e1" : "#f1f5f9"
                }}
                title={product.name}
              >
                {/* Top: Image Aspect Box */}
                <div className="aspect-square w-full rounded-2xl overflow-hidden bg-slate-50 relative shrink-0 select-none pointer-events-none">
                  <img
                    src={getOptimizedImageUrl(product.imageUrl, isMobileViewport)}
                    alt=""
                    referrerPolicy="no-referrer"
                    className="w-full h-full object-cover group-hover:scale-103 transition-transform duration-300 pointer-events-none select-none"
                  />
                </div>

                {/* Bottom info section */}
                <div className="px-2 flex flex-col gap-0.5 text-left flex-1 justify-between font-sans">
                  {/* Title & rating row */}
                  <div>
                    <div className="flex justify-between items-start gap-1">
                      <h5 className="text-[11px] font-bold text-slate-905 line-clamp-1 flex-1 leading-snug">
                        {product.name}
                      </h5>
                      <div className="flex items-center gap-0.5 text-[10.5px] font-bold text-slate-800 shrink-0">
                        <Star className="w-2.5 h-2.5 text-slate-900 fill-slate-900" />
                        <span>{(product.rating || 4.8).toFixed(1)}</span>
                      </div>
                    </div>

                    {/* Subtitle / Category info */}
                    <div className="text-[10px] text-stone-500 font-medium leading-none mt-0.5">
                      {getCategoryName(product.category, subcategories, mainCategories, currentLanguage) || product.category || "Artisanat"}
                    </div>
                  </div>

                  {/* Price & Cart row */}
                  <div className="text-[11px] text-slate-900 leading-none flex items-center justify-between mt-1 pt-1 border-t border-slate-50">
                    <div>
                      <span className="font-extrabold text-[#222222]">
                        {product.price.toLocaleString()} DA
                      </span>
                      <span className="text-stone-500 text-[10px]"> total</span>
                    </div>

                    {/* Quick cart button */}
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        if (isDragging.current) return;
                        handleAddToCart(product, store);
                      }}
                      className="p-1 rounded-full bg-slate-900 hover:bg-rose-500 text-white transition-colors duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-offset-1 focus-visible:ring-slate-900"
                      title="Ajouter au Panier"
                    >
                      <ShoppingBag className="w-2.5 h-2.5" />
                    </button>
                  </div>
                </div>
              </motion.div>
            );
          })
        )}
        
        {/* If store has no products, show placeholder */}
        {store.products.length === 0 && (
          <div className="w-[145px] h-[210px] rounded-2xl border border-dashed border-slate-200 flex items-center justify-center bg-slate-100/50">
            <span className="text-[9px] font-bold text-slate-400 tracking-wide uppercase text-center p-2">No items listed</span>
          </div>
        )}
      </div>

      {/* Right Scroll Button */}
      <button
        type="button"
        onClick={(e) => {
          e.stopPropagation();
          handleScroll("right");
        }}
        className={`absolute -right-[18px] top-[110px] -translate-y-1/2 z-20 w-10 h-10 rounded-full bg-white border border-slate-200/90 shadow-md flex items-center justify-center hover:scale-115 active:scale-95 transition-all duration-200 cursor-pointer focus:outline-none ${
          canScrollRight ? "opacity-100 pointer-events-auto" : "opacity-0 pointer-events-none scale-90"
        }`}
        style={{ color: accentColor }}
        aria-label="Scroll Right"
      >
        <ChevronsRight className="w-5 h-5 stroke-[2.5]" />
      </button>
    </div>
  );
}

// Custom status icon representing two people overlapping, with a check or plus symbol in the bottom-right corner as shown in the mockup/screenshot.
const FollowStatusIcon = ({ className = "w-4 h-4", type = "plus" }: { className?: string; type?: "plus" | "check" }) => {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
    >
      {/* Front-left person */}
      {/* Head */}
      <circle cx="8" cy="11" r="3.5" />
      {/* Torso/Shoulder */}
      <path d="M2 19.5v-1a3 3 0 0 1 3-3h4a3 3 0 0 1 3 3v1" />

      {/* Back-right person (partially overlapped/offset to top right) */}
      {/* Head */}
      <circle cx="15.5" cy="7.5" r="3.5" />
      {/* Torso/Shoulder - curves nicely behind the front person */}
      <path d="M11 14a3 3 0 0 1 3.5-2.5h2a3 3 0 0 1 3 3v0.5" />

      {/* Bottom right indicator symbol */}
      {type === "check" ? (
        // Tick/Checkmark symbol in bottom-right corner
        <polyline points="15.5 17.5 17.5 19.5 22 14" strokeWidth="3.2" className="stroke-emerald-450" />
      ) : (
        // Plus symbol in bottom-right corner
        <path d="M18.5 14.5v6M15.5 17.5h6" strokeWidth="3.2" />
      )}
    </svg>
  );
};

