  const handleSaveSlideProduct = (name: string, imgUrl: string) => {
    if (!editingSlideProduct) return;
    const { slideIdx, prodIdx } = editingSlideProduct;
    setPremierSlides((prev) => {
      const updated = [...prev];
      if (updated[slideIdx] && updated[slideIdx].products) {
        const updatedProducts = [...updated[slideIdx].products];
        if (updatedProducts[prodIdx]) {
          updatedProducts[prodIdx] = {
            ...updatedProducts[prodIdx],
            name: name,
            imgUrl: imgUrl
          };
          updated[slideIdx] = {
            ...updated[slideIdx],
            products: updatedProducts
          };
        }
      }
      return updated;
    });
    setEditingSlideProduct(null);
  };

  const [wishlist, setWishlist] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem("yume_wishlist");
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });
  const [showWishlistOnly, setShowWishlistOnly] = useState<boolean>(false);
  const [isSavedOpen, setIsSavedOpen] = useState<boolean>(false);

  const handleToggleWishlist = (productId: string) => {
    setWishlist((prev) => {
      const isWish = prev.includes(productId);
      const next = isWish ? prev.filter((id) => id !== productId) : [...prev, productId];
      localStorage.setItem("yume_wishlist", JSON.stringify(next));
      // Dispatch storage event to sync other contexts if needed
      window.dispatchEvent(new Event("storage_wishlist_sync"));

      // Also automatically manage comparison list
      if (!isWish) {
        let foundProduct: Product | null = null;
        for (const store of stores) {
          if (store.products) {
            const prod = store.products.find((p) => (p.id === productId || p.name === productId));
            if (prod) {
              foundProduct = prod;
              break;
            }
          }
        }
        if (foundProduct) {
          setComparedProducts((prevComp) => {
            const exists = prevComp.some((p) => p.id === productId || p.name === productId);
            if (!exists && prevComp.length < 3) {
              return [...prevComp, foundProduct!];
            }
            return prevComp;
          });
        }
      } else {
        setComparedProducts((prevComp) => prevComp.filter((p) => (p.id !== productId && p.name !== productId)));
      }

      return next;
    });
  };

  // Listen to cross-context synchronization
  useEffect(() => {
    const handleSync = () => {
      try {
        const saved = localStorage.getItem("yume_wishlist");
        if (saved) {
          setWishlist(JSON.parse(saved));
        }
      } catch (e) {
        console.error(e);
      }
    };
    window.addEventListener("storage_wishlist_sync", handleSync);
    window.addEventListener("storage", handleSync);
    return () => {
      window.removeEventListener("storage_wishlist_sync", handleSync);
      window.removeEventListener("storage", handleSync);
    };
  }, []);

  // Wishlist Price Drop & Restock Monitoring and alert system
  const prevWishlistPriceData = useRef<{ [productId: string]: { price: number; stock: number } }>({});

  useEffect(() => {
    try {
      const saved = localStorage.getItem("yume_wishlist_prices");
      if (saved) {
        prevWishlistPriceData.current = JSON.parse(saved);
      }
    } catch (e) {
      console.warn("Failed to parse initial yume_wishlist_prices:", e);
    }
  }, []);

  useEffect(() => {
    if (!stores || stores.length === 0 || !wishlist || wishlist.length === 0) {
      return;
    }

    const currentPriceData: { [productId: string]: { price: number; stock: number } } = { ...prevWishlistPriceData.current };
    let changed = false;

    // Find all products currently in user wishlist
    wishlist.forEach((productId) => {
      // Find product in stores
      let foundProduct: any = null;
      let foundStoreName = "";

      for (const store of stores) {
        if (store.products) {
          const prod = store.products.find((p) => p.id === productId);
          if (prod) {
            foundProduct = prod;
            foundStoreName = store.name;
            break;
          }
        }
      }

      if (foundProduct) {
        const prevData = prevWishlistPriceData.current[productId];
        const currentPrice = foundProduct.price;
        const currentStock = foundProduct.stock;

        if (prevData) {
          // Check for price drop
          if (currentPrice < prevData.price) {
            const dropAmount = prevData.price - currentPrice;
            const message = `Price dropped on "${foundProduct.name}" by ${dropAmount.toLocaleString()} DA! Get it now for ${currentPrice.toLocaleString()} DA. 🔥`;

            setToasts((prev) => {
              if (prev.some((t) => t.orderId === productId && t.status === "wishlist_price_drop")) {
                return prev;
              }
              const cleanId = Math.random().toString(36).substring(2, 9);
              setTimeout(() => {
                setToasts((current) => current.filter((t) => t.id !== cleanId));
              }, 8000);

              return [
                ...prev,
                {
                  id: cleanId,
                  orderId: productId,
                  storeName: foundStoreName,
                  status: "wishlist_price_drop",
                  message,
                  imageUrl: foundProduct.imageUrl || foundProduct.imgUrl
                }
              ];
            });
          }

          // Check for return to stock
          if (currentStock > 0 && prevData.stock === 0) {
            const message = `"${foundProduct.name}" is back in stock at ${foundStoreName}! 🚀 Grab yours before it's gone.`;

            setToasts((prev) => {
              if (prev.some((t) => t.orderId === productId && t.status === "wishlist_restock")) {
                return prev;
              }
              const cleanId = Math.random().toString(36).substring(2, 9);
              setTimeout(() => {
                setToasts((current) => current.filter((t) => t.id !== cleanId));
              }, 8000);

              return [
                ...prev,
                {
                  id: cleanId,
                  orderId: productId,
                  storeName: foundStoreName,
                  status: "wishlist_restock",
                  message,
                  imageUrl: foundProduct.imageUrl || foundProduct.imgUrl
                }
              ];
            });
          }
        }

        // Update or set baseline price data
        if (!prevData || prevData.price !== currentPrice || prevData.stock !== currentStock) {
          currentPriceData[productId] = { price: currentPrice, stock: currentStock };
          changed = true;
        }
      }
    });

    if (changed) {
      prevWishlistPriceData.current = currentPriceData;
      try {
        localStorage.setItem("yume_wishlist_prices", JSON.stringify(currentPriceData));
      } catch (e) {
        console.warn("Failed to update yume_wishlist_prices in localStorage", e);
      }
    }
  }, [stores, wishlist]);

  // Memoized full product models representing user's saved collections
  const savedCollectionItems = useMemo(() => {
    const items: Array<{ product: Product; store: MerchantStore }> = [];
    if (!stores || !wishlist) return items;
    wishlist.forEach((productId) => {
      for (const store of stores) {
        if (store.products) {
          const prod = store.products.find((p) => p.id === productId || p.name === productId);
          if (prod) {
            items.push({ product: prod, store });
            break;
          }
        }
      }
    });
    return items;
  }, [wishlist, stores]);

  // Persistent Authenticated User State
  const [currentUser, setCurrentUser] = useState<{
    name: string;
    email: string;
    role: "Merchant" | "Buyer";
    storeName?: string;
  } | null>(() => {
    try {
      const saved = localStorage.getItem("yume_current_user");
      return saved ? JSON.parse(saved) : null;
    } catch {
      return null;
    }
  });

  // Synchronize Saved Collection with Firestore when currentUser is active
  useEffect(() => {
    const loadUserWishlist = async () => {
      if (currentUser?.email) {
        try {
          const remoteWishlist = await loadWishlistFromFirestore(currentUser.email);
          if (remoteWishlist) {
            setWishlist(remoteWishlist);
            localStorage.setItem("yume_wishlist", JSON.stringify(remoteWishlist));
          }
        } catch (err) {
          console.error("Error loading saved collection from Firestore:", err);
        }
      }
    };
    loadUserWishlist();
  }, [currentUser?.email]);

  useEffect(() => {
    const saveUserWishlist = async () => {
      if (currentUser?.email) {
        try {
          await saveWishlistToFirestore(currentUser.email, wishlist);
        } catch (err) {
          console.warn("Could not save collection to Firestore (using localStorage fallback):", err);
        }
      }
    };
    saveUserWishlist();
  }, [wishlist, currentUser?.email]);

  // Map state
  const [activeWilaya, setActiveWilaya] = useState<WilayaInfo>(() => {
    try {
      const storedCountry = localStorage.getItem("dz_country") || "United States";
      const hubs = getCommunicativeHubs(storedCountry);
      return hubs[0];
    } catch {
      return getCommunicativeHubs("United States")[0];
    }
  }); // Dynamic default based on country
  const [mapZoom, setMapZoom] = useState<number>(12);
  const [viewportBounds, setViewportBounds] = useState({
    minLat: 36.4,
    maxLat: 36.9,
    minLng: 2.8,
    maxLng: 3.3,
  });

  // --- Consumer Search & Filter state ---
  const [shippingRates, setShippingRates] = useState<{
    algiers: number;
    major: number;
    sahara: number;
    standard: number;
    isFlatRate: boolean;
    flatRateAmount: number;
  }>(() => {
    try {
      const saved = localStorage.getItem("custom_shipping_rates");
      return saved ? JSON.parse(saved) : {
        algiers: 400,
        major: 600,
        sahara: 950,
        standard: 750,
        isFlatRate: false,
        flatRateAmount: 600
      };
    } catch {
      return {
        algiers: 400,
        major: 600,
        sahara: 950,
        standard: 750,
        isFlatRate: false,
        flatRateAmount: 600
      };
    }
  });

  const [searchQuery, setSearchQuery] = useState("");
  const [isSearchFocused, setIsSearchFocused] = useState(false);
  const searchContainerRef = useRef<HTMLDivElement>(null);

  const [recentSearches, setRecentSearches] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem("dz_recent_searches");
      return saved ? JSON.parse(saved) : [];
    } catch (e) {
      return [];
    }
  });

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (searchContainerRef.current && !searchContainerRef.current.contains(e.target as Node)) {
        setIsSearchFocused(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const TRENDING_SEARCH_TERMS = useMemo(() => [
    "Berber Rugs",
    "Handcrafted Pottery",
    "Traditional Kaftan",
    "Artisanal Honey",
    "Leather Goods",
    "Pure Olive Oil"
  ], []);

  const suggestedCategoryMatches = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    const categoriesPool = [
      "Crafts", "Food", "Fashion", "Home", "Electronics", 
      "Home & Kitchen", "Beauty & Personal Care", "Clothing, Shoes & Jewelry", 
      "Sports & Outdoors", "Toys & Games", "Books", "Grocery & Gourmet Food",
      "Traditional Clothing", "Handmade Jewelry", "Artisanal Pottery"
    ];
    if (!q) return categoriesPool.slice(0, 8);
    return categoriesPool.filter(c => c.toLowerCase().includes(q)).slice(0, 6);
  }, [searchQuery]);

  const suggestedStoreMatches = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return [];
    return stores.filter(s => 
      s.name.toLowerCase().includes(q) || 
      (s.city && s.city.toLowerCase().includes(q)) ||
      (s.categories && s.categories.some(c => c.toLowerCase().includes(q)))
    ).slice(0, 3);
  }, [stores, searchQuery]);

  const suggestedProductMatches = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return [];
    const results: { product: any; store: MerchantStore }[] = [];
    for (const s of stores) {
      if (!s.products) continue;
      for (const p of s.products) {
        if (p.name.toLowerCase().includes(q) || (p.category && p.category.toLowerCase().includes(q))) {
          results.push({ product: p, store: s });
          if (results.length >= 4) break;
        }
      }
      if (results.length >= 4) break;
    }
    return results;
  }, [stores, searchQuery]);

  const matchingRecentSearches = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return recentSearches.slice(0, 5);
    return recentSearches.filter(s => s.toLowerCase().includes(q)).slice(0, 5);
  }, [recentSearches, searchQuery]);

  // Advanced Search Criteria States (Mobile-first design)
  const [advSearchStores, setAdvSearchStores] = useState(true);
  const [advSearchProducts, setAdvSearchProducts] = useState(true);
  const [advSearchCategories, setAdvSearchCategories] = useState(true);
  const [advSearchCities, setAdvSearchCities] = useState(true);
  const [advSearchStates, setAdvSearchStates] = useState(true);
  const [advSearchSkuCode, setAdvSearchSkuCode] = useState(true);

  const [advSelectedCity, setAdvSelectedCity] = useState("All");
  const [advSelectedCountry, setAdvSelectedCountry] = useState("All");
  const [advMinRating, setAdvMinRating] = useState(0); // 0, 3.5, 4, 4.5
  const [advPriceSort, setAdvPriceSort] = useState<"none" | "low-to-high" | "high-to-low">("none");

  // Conversational Dialogue Search Session States (Draft inputs inside the panel)
  const [dialogueStep, setDialogueStep] = useState<number>(0);
  const [dlgSelectedOptions, setDlgSelectedOptions] = useState<string[]>([]); // e.g. ['city', 'category', 'product', 'country', 'sku', 'rating', 'price']
  const [dlgCity, setDlgCity] = useState("All");
  const [dlgCountry, setDlgCountry] = useState("All");
  const [dlgProduct, setDlgProduct] = useState("");
  const [dlgCategory, setDlgCategory] = useState("All");
  const [dlgSku, setDlgSku] = useState("");
  const [dlgRating, setDlgRating] = useState(0);
  const [dlgPriceSort, setDlgPriceSort] = useState<"none" | "low-to-high" | "high-to-low">("none");
  const [dlgSearchTarget, setDlgSearchTarget] = useState<"both" | "stores" | "products">("both");
  const [dialogueSearchActive, setDialogueSearchActive] = useState(false);

  // Saved / Applied States for interactive search (copied when user clicks OK)
  const [appliedDlgSelectedOptions, setAppliedDlgSelectedOptions] = useState<string[]>([]);
  const [appliedDlgCity, setAppliedDlgCity] = useState("All");
  const [appliedDlgCountry, setAppliedDlgCountry] = useState("All");
  const [appliedDlgProduct, setAppliedDlgProduct] = useState("");
  const [appliedDlgCategory, setAppliedDlgCategory] = useState("All");
  const [appliedDlgSku, setAppliedDlgSku] = useState("");
  const [appliedDlgRating, setAppliedDlgRating] = useState(0);
  const [appliedDlgPriceSort, setAppliedDlgPriceSort] = useState<"none" | "low-to-high" | "high-to-low">("none");
  const [appliedDlgSearchTarget, setAppliedDlgSearchTarget] = useState<"both" | "stores" | "products">("both");
  const [appliedDialogueSearchActive, setAppliedDialogueSearchActive] = useState(false);

  const resetInteractiveSearch = () => {
    setDlgSelectedOptions([]);
    setDlgCity("All");
    setDlgCountry("All");
    setDlgProduct("");
    setDlgCategory("All");
    setDlgSku("");
    setDlgRating(0);
    setDlgPriceSort("none");
    setDlgSearchTarget("both");

    setAppliedDlgSelectedOptions([]);
    setAppliedDlgCity("All");
    setAppliedDlgCountry("All");
    setAppliedDlgProduct("");
    setAppliedDlgCategory("All");
    setAppliedDlgSku("");
    setAppliedDlgRating(0);
    setAppliedDlgPriceSort("none");
    setAppliedDlgSearchTarget("both");
    setAppliedDialogueSearchActive(false);
  };

  useEffect(() => {
    // If the user navigates away (changes activeTab, activeSection, or closes the panel), reset the draft input interface
    setDlgSelectedOptions([]);
    setDlgCity("All");
    setDlgCountry("All");
    setDlgProduct("");
    setDlgCategory("All");
    setDlgSku("");
    setDlgRating(0);
    setDlgPriceSort("none");
    setDlgSearchTarget("both");
  }, [activeTab, activeSection, dialogueSearchActive]);

  const dialogueFallbacks = useMemo(() => {
    if (!appliedDialogueSearchActive) {
      return {
        productNotFound: false,
        similarProducts: [],
        categoryNotFound: false,
        similarCategories: [],
        storeNotFound: false,
        suggestedStores: []
      };
    }
    
    // Find matching items inside the selected location
    const cityLower = appliedDlgCity.toLowerCase();
    const isCityFiltered = appliedDlgCity !== "All";
    const isCountryFiltered = appliedDlgCountry !== "All";
    
    // 1. Product Fallback check
    let productNotFound = false;
    let similarProducts: any[] = [];
    if (appliedDlgProduct.trim() !== "") {
      const prodLower = appliedDlgProduct.toLowerCase().trim();
      // Count exact product matches in the chosen location
      const exactProdCount = stores.filter(s => {
        const matchesCity = !isCityFiltered || s.wilaya.toLowerCase() === cityLower;
        const matchesCountry = !isCountryFiltered || appliedDlgCountry === "Algeria";
        return matchesCity && matchesCountry;
      }).reduce((acc, s) => {
        return acc + s.products.filter(p => {
          const matchesProd = p.name.toLowerCase().includes(prodLower) || (p.description_en || p.description_fr || "").toLowerCase().includes(prodLower);
          const matchesCat = appliedDlgCategory === "All" || p.category === appliedDlgCategory;
          const matchesPop = appliedDlgRating === 0 || p.rating >= 4.0;
          return matchesProd && matchesCat && matchesPop;
        }).length;
      }, 0);
      
      if (exactProdCount === 0) {
        productNotFound = true;
        // Find similar products in other states/countries
        stores.forEach(s => {
          s.products.forEach(p => {
            const matchesProd = p.name.toLowerCase().includes(prodLower) || (p.description_en || p.description_fr || "").toLowerCase().includes(prodLower);
            if (matchesProd) {
              similarProducts.push({
                type: "product",
                store: s,
                product: p,
                isFallback: true
              });
            }
          });
        });
      }
    }

    // 2. Category Fallback check
    let categoryNotFound = false;
    let similarCategories: any[] = [];
    if (appliedDlgCategory !== "All") {
      // Count items in category in chosen location
      const exactCatCount = stores.filter(s => {
        const matchesCity = !isCityFiltered || s.wilaya.toLowerCase() === cityLower;
        const matchesCountry = !isCountryFiltered || appliedDlgCountry === "Algeria";
        return matchesCity && matchesCountry;
      }).reduce((acc, s) => {
        const matchesStoreCat = s.categories.includes(appliedDlgCategory as any);
        const matchesProdCat = s.products.some(p => p.category === appliedDlgCategory);
        return acc + (matchesStoreCat || matchesProdCat ? 1 : 0);
      }, 0);
      
      if (exactCatCount === 0) {
        categoryNotFound = true;
        // Suggest stores/products in that category from other states/countries
        stores.forEach(s => {
          const matchesStoreCat = s.categories.includes(appliedDlgCategory as any);
          const matchesProdCat = s.products.some(p => p.category === appliedDlgCategory);
          if (matchesStoreCat || matchesProdCat) {
            similarCategories.push({
              type: "store",
              store: s,
              isFallback: true
            });
          }
        });
      }
    }

    // 3. Store Fallback check
    let storeNotFound = false;
    let suggestedStores: any[] = [];
    // If the total filtered search results is 0
    const totalResultsCount = stores.filter(s => {
      let matches = true;
      if (isCityFiltered) matches = matches && s.wilaya.toLowerCase() === cityLower;
      if (isCountryFiltered) matches = matches && appliedDlgCountry === "Algeria";
      if (appliedDlgCategory !== "All") matches = matches && s.categories.includes(appliedDlgCategory as any);
      if (appliedDlgRating > 0) matches = matches && s.rating >= 4.0;
      return matches;
    }).length;

    if (totalResultsCount === 0) {
      storeNotFound = true;
      // Suggest similar stores
      stores.forEach(s => {
        const sharesCategory = appliedDlgCategory !== "All" && s.categories.includes(appliedDlgCategory as any);
        if (sharesCategory) {
          suggestedStores.push(s);
        }
      });
      // If we didn't find any, suggest top-rated general stores
      if (suggestedStores.length === 0) {
        suggestedStores = [...stores].sort((a, b) => b.rating - a.rating).slice(0, 4);
      }
    }

    return {
      productNotFound,
      similarProducts: similarProducts.slice(0, 10),
      categoryNotFound,
      similarCategories: similarCategories.slice(0, 10),
      storeNotFound,
      suggestedStores: suggestedStores.slice(0, 4)
    };
  }, [appliedDialogueSearchActive, appliedDlgCity, appliedDlgCountry, appliedDlgProduct, appliedDlgCategory, appliedDlgRating, stores]);


  // Smart Frame editing overlay state
  const [editingSlideProduct, setEditingSlideProduct] = useState<{ slideIdx: number; prodIdx: number; name: string; imgUrl: string } | null>(null);

  // Recent Visit History State
  const [recentVisits, setRecentVisits] = useState<{id: string, name: string, type: 'store' | 'product', image?: string, rating?: number, wilaya?: string}[]>(() => {
    try {
      const saved = localStorage.getItem("dz_recent_visits");
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const trackVisit = (item: {id: string, name: string, type: 'store' | 'product', image?: string, rating?: number, wilaya?: string}) => {
    setRecentVisits((prev) => {
      const filtered = prev.filter(v => !(v.id === item.id && v.type === item.type));
      const updated = [item, ...filtered].slice(0, 10);
      try {
        localStorage.setItem("dz_recent_visits", JSON.stringify(updated));
      } catch (e) {
        console.error("Failed to save visit", e);
      }
      return updated;
    });
  };

  const saveSearchTerm = (term: string) => {
    const cleanTerm = term.trim();
    if (!cleanTerm) return;
    setRecentSearches((prev) => {
      const filtered = prev.filter((s) => s.toLowerCase() !== cleanTerm.toLowerCase());
      const updated = [cleanTerm, ...filtered].slice(0, 6);
      try {
        localStorage.setItem("dz_recent_searches", JSON.stringify(updated));
      } catch (e) {
        console.error("Failed to save search term", e);
      }
      return updated;
    });
  };

  const [selectedCategory, setSelectedCategory] = useState<string>("All");
  const [randomCategories] = useState<string[]>(() => {
    const allPool = [
      "Crafts",
      "Food",
      "Fashion",
      "Home",
      "Electronics",
      "Home & Kitchen",
      "Beauty & Personal Care",
      "Clothing, Shoes & Jewelry",
      "Sports & Outdoors",
      "Toys & Games",
      "Books",
      "Automotive & Powersports",
      "Garden & Outdoor",
      "Health & Household",
      "Grocery & Gourmet Food",
      "Industrial & Scientific",
      "Collectibles",
      "Music"
    ];
    const shuffled = [...allPool].sort(() => 0.5 - Math.random());
    return ["All", ...shuffled.slice(0, 7)];
  });
  const [filterVerifiedOnly, setFilterVerifiedOnly] = useState(false);
  const [filterPremiumTier, setFilterPremiumTier] = useState<string>("All");
  const [filterMinRating, setFilterMinRating] = useState<number>(0);
  const [filterMinProducts, setFilterMinProducts] = useState<number>(0);
  const [selectedCategories, setSelectedCategories] = useState<string[]>([]);
  const [showAdvancedFilters, setShowAdvancedFilters] = useState<boolean>(false);
  const [showCommerceMap, setShowCommerceMap] = useState<boolean>(true);

  // --- Proximity Search state ---
  const [isProximityActive, setIsProximityActive] = useState<boolean>(false);
  const [proximityRadius, setProximityRadius] = useState<number>(7.5); // Default 7.5km (range 3-200km)
  const [userLocation, setUserLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [isLocating, setIsLocating] = useState<boolean>(false);
  const [proximityCenter, setProximityCenter] = useState<{ lat: number; lng: number; label: string } | null>(null);

  // Selected Store / Product view modal state
  const [selectedStore, setSelectedStore] = useState<MerchantStore | null>(null);
  const [expandedStoreId, setExpandedStoreId] = useState<string | null>(null);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [shareCopied, setShareCopied] = useState<boolean>(false);

  useEffect(() => {
    setProfileScrollY(0);
    merchantLastScrollY.current = 0;
    if (selectedStore) {
      setShowMerchantHeader(true);
    }
  }, [selectedStore?.id]);

  // Cover templates database (controlled by Platform Admin, chosen by Merchant)
  const [coverTemplates, setCoverTemplates] = useState<CoverTemplate[]>(() => {
    try {
      const saved = localStorage.getItem("dz_cover_templates");
      if (saved) {
        const parsed = JSON.parse(saved) as CoverTemplate[];
        let dirty = false;
        
        // Ensure toonhub template enjoys the name "3D Character 01"
        const toonhubIdx = parsed.findIndex(t => t.id === "toonhub");
        if (toonhubIdx !== -1 && parsed[toonhubIdx].name !== "3D Character 01") {
          parsed[toonhubIdx].name = "3D Character 01";
          dirty = true;
        }

        if (!parsed.some(t => t.id === "cover77" || t.id === "77")) {
          const cover77 = INITIAL_COVER_TEMPLATES.find(t => t.id === "cover77");
          if (cover77) {
            parsed.push(cover77);
            dirty = true;
          }
        }
        if (!parsed.some(t => t.id === "mysticflower")) {
          const mysticflower = INITIAL_COVER_TEMPLATES.find(t => t.id === "mysticflower");
          if (mysticflower) {
            parsed.push(mysticflower);
            dirty = true;
          }
        }
        if (dirty) {
          localStorage.setItem("dz_cover_templates", JSON.stringify(parsed));
        }
        return parsed;
      }
      return INITIAL_COVER_TEMPLATES;
    } catch (e) {
      return INITIAL_COVER_TEMPLATES;
    }
  });

  const saveCoverTemplates = (newTemplates: CoverTemplate[]) => {
    setCoverTemplates(newTemplates);
    try {
      localStorage.setItem("dz_cover_templates", JSON.stringify(newTemplates));
    } catch (e) {
      console.error("Failed to save cover templates", e);
    }
  };

  // --- Social Media Stories System State ---
  const [activeStoryStore, setActiveStoryStore] = useState<MerchantStore | null>(null);
  const [activeStorySlideIndex, setActiveStorySlideIndex] = useState<number>(0);
  const [isStoryPlaying, setIsStoryPlaying] = useState<boolean>(true);
  const [isStoryAudioMuted, setIsStoryAudioMuted] = useState<boolean>(false);
  const [currentVideoDuration, setCurrentVideoDuration] = useState<number | null>(null);
  const [addStoryModalStore, setAddStoryModalStore] = useState<MerchantStore | null>(null);
  const [activeStoryMoreOpen, setActiveStoryMoreOpen] = useState<boolean>(false);
  const [storyCommentText, setStoryCommentText] = useState<string>("");
  const [storyMuteStatus, setStoryMuteStatus] = useState<Record<string, boolean>>({});
  const [storyToastText, setStoryToastText] = useState<string>("");
  const [storyToDeleteId, setStoryToDeleteId] = useState<string | null>(null);
  const [addStoryModalError, setAddStoryModalError] = useState<string>("");
  const [storyMediaLoading, setStoryMediaLoading] = useState<boolean>(true);
  const [isDataSaverEnabled, setIsDataSaverEnabled] = useState<boolean>(() => localStorage.getItem("dz_story_data_saver") === "true");
  const [dataSaverManualLoaded, setDataSaverManualLoaded] = useState<Record<string, boolean>>({});
  const [selectedAiProvider, setSelectedAiProvider] = useState<"gemini" | "nvidia" | "openai" | "other">("gemini");

  // --- Facebook-Style Reels System State ---
  const [activeReelsStore, setActiveReelsStore] = useState<MerchantStore | null>(null);
  const [reelsBackTarget, setReelsBackTarget] = useState<{ product: Product; store: MerchantStore } | null>(null);
  const [activeReelIndex, setActiveReelIndex] = useState<number>(0);
  const [currentReelLiked, setCurrentReelLiked] = useState<Record<string, boolean>>({});
  const [currentReelLikesCount, setCurrentReelLikesCount] = useState<Record<string, number>>({});
  const [reelComments, setReelComments] = useState<Record<string, { id: string; author: string; avatar: string; comment: string; date: string }[]>>({});
  const [newReelCommentText, setNewReelCommentText] = useState<string>("");
  const [showReelCommentsDrawer, setShowReelCommentsDrawer] = useState<boolean>(false);
  const [showReelMetadataId, setShowReelMetadataId] = useState<string | null>(null);
  const [isCleanReelsMode, setIsCleanReelsMode] = useState<boolean>(false);
  const [isReelMuted, setIsReelMuted] = useState<boolean>(false);
  const [reelShareNotification, setReelShareNotification] = useState<string>("");
  const [previewMutedReels, setPreviewMutedReels] = useState<Record<string, boolean>>({});
  const [hoveredReelId, setHoveredReelId] = useState<string | null>(null);
  const [activeReelMoreOpen, setActiveReelMoreOpen] = useState<boolean>(false);
  
  
  // Real-time story clock to trigger UI updates and automatic deletions
  const [storyClockTime, setStoryClockTime] = useState<number>(Date.now());
  
  useEffect(() => {
    const timer = setInterval(() => {
      setStoryClockTime(Date.now());
    }, 1000);
    return () => clearInterval(timer);
  }, []);
  
  const [customStoriesByStore, setCustomStoriesByStore] = useState<Record<string, {
    id: string;
    type: "image" | "video" | "text";
    url: string;
    text: string;
    bgColor?: string;
    textColor?: string;
    productId?: string;
    productName?: string;
    hashtags?: string;
    discountPercent?: number;
    durationHours?: number;
    createdAt?: number;
  }[]>>(() => {
    const saved = localStorage.getItem("dz_store_stories");
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {
        console.error(e);
      }
    }
    return {};
  });

  // Automatically delete expired stories from the customStoriesByStore state (and persistence) when countdown reaches zero
  useEffect(() => {
    const now = Date.now();
    setCustomStoriesByStore((prev) => {
      let changed = false;
      const cloned = { ...prev };
      
      Object.keys(cloned).forEach((storeId) => {
        const list = cloned[storeId];
        if (Array.isArray(list)) {
          let hasChange = false;
          const activeList = list.map((slide) => {
            if (!slide) return null;
            const slideId = slide.id || "";
            const timestamp = slide.createdAt || (slideId.startsWith("story_") ? parseInt(slideId.replace("story_", ""), 10) : now);
            const hrs = slide.durationHours || 24;
            const limitMs = hrs * 60 * 60 * 1000;
            const isExpired = (now - timestamp) >= limitMs;
            if (isExpired) {
              hasChange = true;
              return null;
            }
            return slide;
          });
          if (hasChange) {
            cloned[storeId] = activeList;
            changed = true;
          }
        }
      });
      
      return changed ? cloned : prev;
    });
  }, [storyClockTime]);

  const [storyAnalytics, setStoryAnalytics] = useState<Record<string, { views: number; reactions: number; clicks: number }>>(() => {
    try {
      const saved = localStorage.getItem("dz_story_analytics");
      return saved ? JSON.parse(saved) : {};
    } catch {
      return {};
    }
  });

  useEffect(() => {
    localStorage.setItem("dz_story_analytics", JSON.stringify(storyAnalytics));
  }, [storyAnalytics]);

  const [merchantToastQueue, setMerchantToastQueue] = useState<{ id: string; storeId: string; type: "heart" | "dm"; message: string; createdAt: number; storyId?: string; storyText?: string; commentText?: string }[]>(() => {
    try {
      const saved = localStorage.getItem("dz_merchant_story_toasts");
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  useEffect(() => {
    localStorage.setItem("dz_merchant_story_toasts", JSON.stringify(merchantToastQueue));
  }, [merchantToastQueue]);

  const [deletedStoryIdsByStore, setDeletedStoryIdsByStore] = useState<Record<string, string[]>>(() => {
    try {
      const saved = localStorage.getItem("dz_store_deleted_stories");
      return saved ? JSON.parse(saved) : {};
    } catch {
      return {};
    }
  });

  useEffect(() => {
    localStorage.setItem("dz_store_deleted_stories", JSON.stringify(deletedStoryIdsByStore));
  }, [deletedStoryIdsByStore]);

  const [deletedReelIdsByStore, setDeletedReelIdsByStore] = useState<Record<string, string[]>>(() => {
    try {
      const saved = localStorage.getItem("dz_store_deleted_reels");
      return saved ? JSON.parse(saved) : {};
    } catch {
      return {};
    }
  });

  useEffect(() => {
    localStorage.setItem("dz_store_deleted_reels", JSON.stringify(deletedReelIdsByStore));
  }, [deletedReelIdsByStore]);

  useEffect(() => {
    localStorage.setItem("dz_store_stories", JSON.stringify(customStoriesByStore));
  }, [customStoriesByStore]);

  const getStoreReels = (store: MerchantStore) => {
    const category = store.categories[0] || "Crafts";
    
    interface ReelComment {
      id: string;
      author: string;
      avatar: string;
      comment: string;
      date: string;
    }

    interface StoreReel {
      id: string;
      videoUrl: string;
      coverUrl: string;
      title: string;
      description: string;
      views: string;
      likes: number;
      commentsCount: number;
      comments: ReelComment[];
      productId?: string;
      videoMetadata?: {
        duration?: string;
        resolution?: string;
        format?: string;
      };
    }

    const defaultComments: ReelComment[] = [
      { id: "c1", author: "Yasmine Belkacem", avatar: "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=150", comment: "C'est magnifique ! Quel travail incroyable ❤️🇩🇿", date: "2h ago" },
      { id: "c2", author: "Karim Dz", avatar: "https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=150", comment: "Est-ce qu'il y a livraison sur Oran ??", date: "4h ago" },
      { id: "c3", author: "Amel B.", avatar: "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150", comment: "Très satisfaite de ma commande, qualité incroyable !", date: "1d ago" }
    ];

    const reelsList: StoreReel[] = [];
    const prods = store.products || [];

    if (category === "Food") {
      reelsList.push(
        {
          id: `${store.id}_reel_1`,
          videoUrl: "https://assets.mixkit.co/videos/preview/mixkit-golden-olive-oil-poured-into-a-bowl-43485-large.mp4",
          coverUrl: prods[0]?.imageUrl || "https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?auto=format&fit=crop&w=400",
          title: "Tradition et Terroir 🌿",
          description: "La pureté dorée. Découvrez les étapes de récolte et le secret du goût unique de notre miel de forêt sauvage. Artisanal, bio, et récolté à l'ancienne. 🇩🇿 #algerie #tradition #bio",
          views: "18.2K",
          likes: 1240,
          commentsCount: 3,
          comments: [...defaultComments],
          productId: prods[0]?.id
        },
        {
          id: `${store.id}_reel_2`,
          videoUrl: "https://assets.mixkit.co/videos/preview/mixkit-pouring-hot-tea-into-glass-cups-42337-large.mp4",
          coverUrl: prods[1]?.imageUrl || "https://images.unsplash.com/photo-1576092768241-dec231879fc3?auto=format&fit=crop&w=400",
          title: "Art de Thé du Sahara 🐪",
          description: "La rime parfaite du brûleur de thé sous la fraîcheur d'un soir saharien de Timimoun. Un goût royal d'épices d'Afrique du Nord. ☕✨ #sahara #degletnoor #culinary",
          views: "25.4K",
          likes: 2840,
          commentsCount: 4,
          comments: [
            { id: "c4", author: "Omar Biskra", avatar: "https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=150", comment: "Le vrai thé algérien ! Ya3tikom el saha 👌", date: "1h ago" },
            ...defaultComments
          ],
          productId: prods[1]?.id
        }
      );
    } else if (category === "Crafts" || category === "Home") {
      reelsList.push(
        {
          id: `${store.id}_reel_1`,
          videoUrl: "https://assets.mixkit.co/videos/preview/mixkit-hands-of-a-potter-shaping-clay-on-a-wheel-40615-large.mp4",
          coverUrl: prods[0]?.imageUrl || "https://images.unsplash.com/photo-1578749556568-bc2c40e68b61?auto=format&fit=crop&w=400",
          title: "Art de la Poterie d'Argile 🏺",
          description: "Chaque courbe raconte l'Argile d'une terre millénaire. Regardez comment naît votre vase Kaolo traditionnel de Kabylie, sculpté et lissé entièrement à la main. ✨ #kabylie #artisanat #algeria",
          views: "34.5K",
          likes: 4230,
          commentsCount: 3,
          comments: [...defaultComments],
          productId: prods[0]?.id
        },
        {
          id: `${store.id}_reel_2`,
          videoUrl: "https://assets.mixkit.co/videos/preview/mixkit-weaving-traditional-textile-pattern-on-a-loom-41824-large.mp4",
          coverUrl: prods[1]?.imageUrl || "https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=400",
          title: "Tissage Kabyle Royal 🧶",
          description: "Derrière chaque symbole brodé d'indigo et de pourpre se cachent les chants d'amour des montagneuses. Notre chef-d'œuvre de laine mérinos pure. ❤️🇩🇿 #traditional #decor #cozy",
          views: "22.1K",
          likes: 2150,
          commentsCount: 4,
          comments: [
            { id: "c5", author: "Lina Alger", avatar: "https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=150", comment: "Magnifique couleur ! Le travail est exceptionnel.", date: "30m ago" },
            ...defaultComments
          ],
          productId: prods[1]?.id
        }
      );
    } else {
      reelsList.push(
        {
          id: `${store.id}_reel_1`,
          videoUrl: "https://assets.mixkit.co/videos/preview/mixkit-weaving-traditional-textile-pattern-on-a-loom-41824-large.mp4",
          coverUrl: prods[0]?.imageUrl || "https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=400",
          title: "Broderie Karakou Traditionnelle 👑",
          description: "Une précision chirurgicale combinant pas moins de 40 heures de broderie de fil de soie d'or pur. Une création d'une élégance rare pour briller. 🇩🇿 #karakou #hautecouture #algerienne",
          views: "45.1K",
          likes: 5620,
          commentsCount: 3,
          comments: [...defaultComments],
          productId: prods[0]?.id
        },
        {
          id: `${store.id}_reel_2`,
          videoUrl: "https://assets.mixkit.co/videos/preview/mixkit-baking-traditional-bread-in-an-outdoor-oven-43283-large.mp4",
          coverUrl: prods[1]?.imageUrl || "https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&w=400",
          title: "Matières Nobles & Tannerie 👜",
          description: "La perfection réside dans les détails. Notre cuir pleine fleur est sélectionné, assemblé et patiné pièce par pièce à Alger. Pour durer toute une vie. ✨ #fashion #luxury #handmade",
          views: "15.9K",
          likes: 1120,
          commentsCount: 3,
          comments: [...defaultComments],
          productId: prods[1]?.id
        }
      );
    }

    // Dynamic scanning of products to append uploaded reels or linked videos with their metadata
    prods.forEach(prod => {
      if (prod.videoUrls && prod.videoUrls.length > 0) {
        prod.videoUrls.forEach((url, uidx) => {
          if (!reelsList.some(r => r.videoUrl === url)) {
            const metadata = prod.videoMetadata && prod.videoMetadata[url] 
              ? prod.videoMetadata[url] 
              : { duration: "0:30", resolution: "1080p (1080x1920)", format: "MP4" };
            reelsList.unshift({
              id: `${store.id}_prod_reel_${prod.id}_${uidx}`,
              videoUrl: url,
              coverUrl: prod.imageUrl || (prod.images && prod.images[0]) || "https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=400",
              title: `${prod.name} Showcase ✨`,
              description: prod.description || `Special showcase for our beautiful ${prod.name}. Watch to learn more!`,
              views: "1.4K",
              likes: 184,
              commentsCount: 0,
              comments: [],
              productId: prod.id,
              videoMetadata: {
                duration: metadata.duration || "0:30",
                resolution: metadata.resolution || "1080p (1080x1920)",
                format: metadata.format || "MP4"
              }
            });
          }
        });
      } else if (prod.videoUrl) {
        if (!reelsList.some(r => r.videoUrl === prod.videoUrl)) {
          const metadata = prod.videoMetadata && prod.videoMetadata[prod.videoUrl!] 
            ? prod.videoMetadata[prod.videoUrl!] 
            : { duration: "0:30", resolution: "1080p (1080x1920)", format: "MP4" };
          reelsList.unshift({
            id: `${store.id}_prod_reel_single_${prod.id}`,
            videoUrl: prod.videoUrl!,
            coverUrl: prod.imageUrl || "https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=400",
            title: `${prod.name} Preview 🏺`,
            description: prod.description || `Exclusive video introduction to ${prod.name}.`,
            views: "920",
            likes: 67,
            commentsCount: 0,
            comments: [],
            productId: prod.id,
            videoMetadata: {
              duration: metadata.duration || "0:30",
              resolution: metadata.resolution || "1080p (1080x1920)",
              format: metadata.format || "MP4"
            }
          });
        }
      }
    });

    const deletedReelIds = deletedReelIdsByStore[store.id] || [];
    return reelsList.filter(r => !deletedReelIds.includes(r.id));
  };

  const getStoreStories = (store: MerchantStore) => {
    const custom = customStoriesByStore[store.id] || [];
    const deletedIds = deletedStoryIdsByStore[store.id] || [];
    
    const DURATION_OPTIONS = [
      { label: "1 Hour", value: 1 },
      { label: "3 Hours", value: 3 },
      { label: "6 Hours", value: 6 },
      { label: "12 Hours", value: 12 },
      { label: "24 Hours (1 Day)", value: 24 },
      { label: "2 Days", value: 48 },
      { label: "3 Days", value: 72 },
      { label: "5 Days", value: 120 },
      { label: "1 Week", value: 168 },
    ];

    let durationHours = 24; // Default to 24 hours
    try {
      const savedIdxStr = localStorage.getItem(`story_duration_idx_${store.id}`);
      if (savedIdxStr) {
        const savedIdx = parseInt(savedIdxStr, 10);
        if (savedIdx >= 0 && savedIdx < DURATION_OPTIONS.length) {
          durationHours = DURATION_OPTIONS[savedIdx].value;
        }
      }
    } catch (e) {
      console.error(e);
    }
    
    // Filter out stories that have expired or exceeded dynamic custom limits
    const activeCustom = custom.filter((slide) => {
      if (!slide || !slide.id) return false;
      if (deletedIds.includes(slide.id)) return false;
      const slideDuration = slide.durationHours || durationHours;
      const timestamp = slide.createdAt || (slide.id.startsWith("story_") ? parseInt(slide.id.replace("story_", ""), 10) : Date.now());
      if (timestamp) {
        const elapsedMs = Date.now() - timestamp;
        const limitMs = slideDuration * 3600 * 1000;
        return elapsedMs < limitMs;
      }
      return true;
    });

    const defaults: {
      id: string;
      type: "image" | "video" | "text";
      url: string;
      text: string;
      bgColor?: string;
      textColor?: string;
      productId?: string;
      productName?: string;
      createdAt?: number;
      hideAfter24h?: boolean;
      promotionBadge?: string;
    }[] = [
      {
        id: "default_intro",
        type: "image" as const,
        url: store.banner || "https://images.unsplash.com/photo-1513519245088-0e12902e5a38?auto=format&fit=crop&w=1200&q=80",
        text: `✨ Bienvenue chez ${store.name}! Découvrez notre héritage d'artisanat d'art et d'excellence. 🇩🇿`,
        bgColor: "#1e293b",
        textColor: "#ffffff"
      }
    ];

    if (store.products && store.products.length > 0) {
      store.products.slice(0, 2).forEach((prod) => {
        defaults.push({
          id: `default_prod_${prod.id}`,
          type: "image" as const,
          url: prod.imageUrl || "https://images.unsplash.com/photo-1581291518633-83b4ebd1d83e?auto=format&fit=crop&w=600&q=80",
          text: `🔥 COUP DE CŒUR : Découvrez "${prod.name}" disponible dès maintenant pour ${prod.price.toLocaleString()} DZD !`,
          bgColor: "#0f172a",
          textColor: "#ffffff",
          productId: prod.id,
          productName: prod.name
        });
      });
    }

    defaults.push({
      id: "default_delivery",
      type: "image" as const,
      url: "https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1200&q=80",
      text: "🚚 Livraison Express sécurisée dans les 58 Wilayas d'Algérie ! Paiement cash à la livraison (COD).",
      bgColor: "#020617",
      textColor: "#ffffff"
    });

    const activeDefaults = defaults.filter(d => !deletedIds.includes(d.id));

    return [...activeCustom, ...activeDefaults];
  };

  // Track context for returning back to the last page/view from the single store profile modal view
  const lastStateBeforeStoreOpen = useRef<{ tab: "marketplace" | "merchant" | "admin"; showMap: boolean }>({
    tab: activeTab,
    showMap: showCommerceMap
  });
  const [previousViewContext, setPreviousViewContext] = useState<{ tab: "marketplace" | "merchant" | "admin"; showMap: boolean } | null>(null);
  const [isLiveEditing, setIsLiveEditing] = useState(false);
  const [originalStoreBackup, setOriginalStoreBackup] = useState<MerchantStore | null>(null);
  const [isBrandingBarHovered, setIsBrandingBarHovered] = useState(false);

  const storyVideoRef = useRef<HTMLVideoElement | null>(null);
  const reelVideoRef = useRef<HTMLVideoElement | null>(null);
  const primaryLayoutRef = useRef<HTMLElement | null>(null);

  // Intersection Observer to automatically play when visible and pause when hidden/exited from viewport
  useEffect(() => {
    if (typeof window === "undefined" || !("IntersectionObserver" in window)) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setIsStoryPlaying(true);
            if (storyVideoRef.current) {
              storyVideoRef.current.play().catch(() => {});
            }
          } else {
            setIsStoryPlaying(false);
            if (storyVideoRef.current) {
              storyVideoRef.current.pause();
            }
          }
        });
      },
      {
        root: null, // viewport intersection relative to app structure
        threshold: 0.15,
      }
    );

    const currentVideo = storyVideoRef.current;
    if (currentVideo) {
      observer.observe(currentVideo);
    }

    return () => {
      if (currentVideo) {
        observer.unobserve(currentVideo);
      }
      observer.disconnect();
    };
  }, [activeStoryStore, activeStorySlideIndex]);

  useEffect(() => {
    if (storyVideoRef.current) {
      if (isStoryPlaying) {
        storyVideoRef.current.play().catch(() => {});
      } else {
        storyVideoRef.current.pause();
      }
    }
  }, [isStoryPlaying, activeStorySlideIndex, activeStoryStore]);

  useEffect(() => {
    if (activeStoryStore) {
      const stories = getStoreStories(activeStoryStore);
      const currentSlide = stories[activeStorySlideIndex];
      if (currentSlide) {
        if (currentSlide.type === "text") {
          setStoryMediaLoading(false);
        } else {
          setStoryMediaLoading(true);
        }
      }
    }
  }, [activeStoryStore?.id, activeStorySlideIndex]);

  // Programmatic Robust Reels Autoplay
  useEffect(() => {
    if (!activeReelsStore) return;
    const reels = getStoreReels(activeReelsStore);
    if (!reels || reels.length === 0) return;
    const currentReel = reels[activeReelIndex] || reels[0];
    if (!currentReel) return;

    // Only attempt playback operations if the active reel is a native video
    const parsed = parseSocialVideoUrl(currentReel.videoUrl);
    if (parsed.type !== "video") return;

    const isVid = reelVideoRef.current;
    if (isVid) {
      const playPromise = isVid.play();
      if (playPromise !== undefined) {
        playPromise.catch((error) => {
          console.warn("Unmuted autoplay failed, falling back to muted autoplay:", error);
          // Auto-fallback to muted to ensure it plays
          setIsReelMuted(true);
          isVid.muted = true;
          isVid.play().catch((err) => {
            console.warn("Muted autoplay failed or source is loading/unsupported:", err);
          });
        });
      }
    }
  }, [activeReelsStore, activeReelIndex]);

  useEffect(() => {
    if (!selectedStore) {
      lastStateBeforeStoreOpen.current = {
        tab: activeTab,
        showMap: showCommerceMap
      };
      setPreviousViewContext({
        tab: activeTab,
        showMap: showCommerceMap
      });
    }
  }, [activeTab, showCommerceMap, selectedStore]);

  // --- Social Media Story System State & Autoplay Timer ---
  const [reactions, setReactions] = useState<{ id: string; emoji: string; left: number }[]>([]);

  const handleAddReaction = (emoji: string) => {
    const newReaction = {
      id: `react_${Date.now()}_${Math.random()}`,
      emoji,
      left: 20 + Math.random() * 60,
    };
    setReactions((prev) => [...prev.slice(-30), newReaction]);

    if (activeStoryStore) {
      const activeStories = getStoreStories(activeStoryStore);
      const currentSlide = activeStories[activeStorySlideIndex];
      if (currentSlide) {
        setStoryAnalytics(prev => {
          const id = currentSlide.id;
          const current = prev[id] || { views: 0, reactions: 0, clicks: 0 };
          return {
            ...prev,
            [id]: {
              ...current,
              reactions: current.reactions + 1
            }
          };
        });

        if (emoji === "❤️" || emoji === "💬" || emoji === "🔥") {
          const commentVal = emoji === "💬" ? (storyCommentText.trim() || "Hello!") : undefined;

          const messageAr = emoji === "❤️"
            ? `تفاعل عميل بقلب ❤️ على قصتك!`
            : emoji === "💬"
            ? `أرسل عميل رسالة مباشرة: "${commentVal}"`
            : `شارك عميل قصتك عبر رسالة مباشرة! 🚀`;

          const messageEn = emoji === "❤️"
            ? `A customer reacted with ❤️ to your story slide!`
            : emoji === "💬"
            ? `Direct message received: "${commentVal}"`
            : `A customer shared your story slide! 🚀`;

          const newNotification = {
            id: `alert_${Date.now()}_${Math.random()}`,
            storeId: activeStoryStore.id,
            type: emoji === "❤️" ? "heart" as const : "dm" as const,
            message: currentLanguage === "ar" ? messageAr : messageEn,
            createdAt: Date.now(),
            storyId: currentSlide.id,
            storyText: currentSlide.text || (currentSlide.productName ? `Promo: ${currentSlide.productName}` : "Ordinary Slide"),
            commentText: commentVal,
            emoji
          };

          setMerchantToastQueue(prevQueue => [newNotification, ...prevQueue.slice(0, 100)]);
        }
      }
    }
  };

  useEffect(() => {
    if (activeStoryStore) {
      const activeStories = getStoreStories(activeStoryStore);
      const currentSlide = activeStories[activeStorySlideIndex];
      if (currentSlide) {
        setStoryAnalytics(prev => {
          const id = currentSlide.id;
          const current = prev[id] || { views: 0, reactions: 0, clicks: 0 };
          return {
            ...prev,
            [id]: {
              ...current,
              views: current.views + 1
            }
          };
        });
      }
    }
  }, [activeStoryStore?.id, activeStorySlideIndex]);

  useEffect(() => {
    if (!activeStoryStore) {
      setReactions([]); // reset reactions when story closed
      setCurrentVideoDuration(null);
      return;
    }
    const stories = getStoreStories(activeStoryStore);
    if (stories.length === 0) return;

    if (!isStoryPlaying) return;

    const currentSlide = stories[activeStorySlideIndex];
    if (!currentSlide) return;

    const needsManualLoad = isDataSaverEnabled && 
      (currentSlide.type === "image" || currentSlide.type === "video") && 
      !dataSaverManualLoaded[currentSlide.id];

    // Pause timer if media is loading or waiting for Data Saver manual trigger
    if (storyMediaLoading || needsManualLoad) return;

    const durationMs = (currentSlide.type === "video" && currentVideoDuration)
      ? currentVideoDuration * 1000
      : 5000;

    const timer = setTimeout(() => {
      if (activeStorySlideIndex < stories.length - 1) {
        setActiveStorySlideIndex((prev) => prev + 1);
        setCurrentVideoDuration(null);
      } else {
        setActiveStoryStore(null); // automatic timeout close
        setCurrentVideoDuration(null);
      }
    }, durationMs);

    return () => clearTimeout(timer);
  }, [activeStoryStore, activeStorySlideIndex, isStoryPlaying, currentVideoDuration, storyMediaLoading, isDataSaverEnabled, dataSaverManualLoaded]);
  
