      const isBuyer = currentUser?.role === "Buyer";
      const hasSavedBuyerStyles = buyerSavedWidth !== null || buyerSavedGap !== null;
      const useBuyerCustom = isBuyer && hasSavedBuyerStyles;

      const minWidthStr = (useBuyerCustom && buyerSavedWidth)
        ? `${buyerSavedWidth}px`
        : selectedStore.designSettings?.gridCardMinWidth || "300px";
        
      const gapStr = (useBuyerCustom && buyerSavedGap)
        ? `${buyerSavedGap}px`
        : selectedStore.designSettings?.gridCardGap || "20px";
      
      const parsedWidth = parseInt(minWidthStr, 10) || 200;
