  const handleUpdateStoreDesignSetting = (key: string, value: any) => {
    if (!selectedStore) return;
    
    setSelectedStore(prev => {
      if (!prev) return null;
      const updated = {
        ...prev,
        designSettings: {
          ...(prev.designSettings || {}),
          [key]: value
        }
      };
      // Update global stores list in real-time
      setStores(prevStores => prevStores.map(s => s.id === prev.id ? updated : s));
      return updated;
    });
  };

  const handleAddBuyerModificationLog = (storeId: string, action: string) => {
    if (!currentUser || (currentUser.role !== "Buyer" && currentUser.role !== "Merchant")) return;

    const userAgent = navigator.userAgent;
    let device = "Desktop Device";
    if (/Mobi|Android|iPhone/i.test(userAgent)) {
      device = "Mobile Device";
    } else if (/Tablet|iPad/i.test(userAgent)) {
      device = "Tablet Device";
    }
    
    const mockIp = "197.204." + (currentUser.name.charCodeAt(0) % 255) + "." + (currentUser.name.charCodeAt(currentUser.name.length - 1) % 255);

    const newEntry = {
      id: "log_" + Date.now() + "_" + Math.floor(Math.random() * 1000),
      buyerName: currentUser.name,
      buyerEmail: currentUser.email,
      action: action,
      timestamp: new Date().toISOString(),
      device: device,
      ip: mockIp
    };

    setStores(prevStores => {
      const updatedStores = prevStores.map(s => {
        if (s.id === storeId) {
          const currentHistory = s.authorizationHistory || [];
          const filtered = currentHistory.filter(h => !(h.buyerEmail === currentUser.email && h.action === action));
          const updatedHistory = [newEntry, ...filtered].slice(0, 50);
          return {
            ...s,
            authorizationHistory: updatedHistory
          };
        }
        return s;
      });
      return updatedStores;
    });

    setSelectedStore(prev => {
      if (prev && prev.id === storeId) {
        const currentHistory = prev.authorizationHistory || [];
        const filtered = currentHistory.filter(h => !(h.buyerEmail === currentUser.email && h.action === action));
        const updatedHistory = [newEntry, ...filtered].slice(0, 50);
        return {
          ...prev,
          authorizationHistory: updatedHistory
        };
      }
      return prev;
    });
  };

