  const handleAddShoppingItem = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newShoppingItem.trim()) return;

    const itemName = newShoppingItem.trim();
    setNewShoppingItem("");
    setSuggestingCategory(true);

    let suggestedCategory = "Other";

    if (!navigator.onLine) {
      // Local client-side smart category categorizer when offline
      const lower = itemName.toLowerCase();
      if (lower.includes("date") || lower.includes("apple") || lower.includes("orange") || lower.includes("banana") || lower.includes("lemon") || lower.includes("tomato")) {
        suggestedCategory = "Produce";
      } else if (lower.includes("milk") || lower.includes("cheese") || lower.includes("butter") || lower.includes("yogurt") || lower.includes("lben")) {
        suggestedCategory = "Dairy";
      } else if (lower.includes("bread") || lower.includes("khobz") || lower.includes("baguette") || lower.includes("brioche")) {
        suggestedCategory = "Bakery";
      } else if (lower.includes("oil") || lower.includes("couscous") || lower.includes("rice") || lower.includes("pasta") || lower.includes("sugar") || lower.includes("flour") || lower.includes("salt")) {
        suggestedCategory = "Pantry";
      } else if (lower.includes("water") || lower.includes("juice") || lower.includes("soda") || lower.includes("tea") || lower.includes("coffee") || lower.includes("gazouz")) {
        suggestedCategory = "Beverages";
      } else {
        suggestedCategory = "General";
      }
      setSuggestingCategory(false);
    } else {
      try {
        const response = await fetch("/api/suggest-category", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ itemName }),
        });
        if (response.ok) {
          const data = await response.json();
          suggestedCategory = data.category || "Other";
        }
      } catch (error) {
        console.error("Failed to fetch category suggestion:", error);
      } finally {
        setSuggestingCategory(false);
      }
    }

    const newItem = {
      id: Date.now().toString(),
      name: itemName,
      category: suggestedCategory,
      checked: false
    };

    setShoppingListItems(prev => [newItem, ...prev]);
  };

