                  <span className="absolute top-2.5 left-2.5 bg-gradient-to-r from-red-650 to-rose-600 text-white font-black text-[9px] px-2.5 py-1 rounded-r-lg rounded-tl-lg shadow-sm animate-pulse">
                    COIN BARGAIN
                  </span>

                  {selectedProduct.safe === false && (
                    <div className="absolute top-2.5 right-2.5 bg-amber-500 text-[8px] font-extrabold text-slate-950 px-2 py-0.5 rounded-full shadow flex items-center gap-1">
                      <AlertTriangle className="w-2.5 h-2.5" /> Flagged Compliance
                    </div>
                  )}

