                    { id: "details", label: currentLanguage === "ar" ? "تفاصيل" : currentLanguage === "fr" ? "Détails" : "Details" },
                    { id: "specs", label: currentLanguage === "ar" ? "المواصفات" : currentLanguage === "fr" ? "Fiche Technique" : "Fiche Technique" },
                    { id: "reviews", label: currentLanguage === "ar" ? "الآراء (4.9)" : currentLanguage === "fr" ? "Avis (4.9)" : "Reviews (4.9)" },
                    { id: "guarantees", label: currentLanguage === "ar" ? "خدمات Choice" : currentLanguage === "fr" ? "Services Choice" : "Choice Services" }
